function kpis(){if(document.querySelector('.t2-pro-kpis'))return;const home=document.querySelector('[data-screen-panel="home"]');if(!home)return;const grid=document.createElement('section');grid.className='t2-pro-kpis';[[t('gross'),'grossTotal','green'],[t('commission'),'summaryCommission','purple'],[t('totalExpenses'),'summaryExpenses','red'],[t('net'),'netTotal','blue']].forEach(([l,id,tone])=>{const card=document.createElement('article');card.className='t2-pro-kpi';card.dataset.tone=tone;card.innerHTML=`<small>${l}</small><strong data-copy="${id}">${txt(id,'R$ 0,00')}</strong>`;grid.append(card)});home.prepend(grid)}
