function updateCharts(){const bars=document.querySelector('.t2-pro-bars');if(!bars)return;const now=new Date(),months=[];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);months.push({m:d.getMonth(),y:d.getFullYear(),label:d.toLocaleDateString(lang()==='en'?'en-US':'pt-BR',{month:'short'}).replace('.','')})}const series=chartSeries(months),max=Math.max(1,...series.flatMap(x=>[x.gross,x.expenses]));bars.replaceChildren();series.forEach(x=>{const set=document.createElement('div');set.className='t2-pro-barset';const g=Math.max(x.gross?8:2,Math.round(x.gross/max*100)),e=Math.max(x.expenses?8:2,Math.round(x.expenses/max*100));set.innerHTML=`<i class="t2-pro-bar" style="height:${g}%" title="${x.label}/${x.y} — ${t('gross')}: ${money(x.gross)}"></i><i class="t2-pro-bar exp" style="height:${e}%" title="${x.label}/${x.y} — ${t('totalExpenses')}: ${money(x.expenses)}"></i><small>${x.label}<br><b>${money(x.gross)}</b><em>${money(x.expenses)}</em></small>`;bars.append(set)});const donut=document.querySelector('.t2-pro-donut');if(donut){const gross=Math.max(0,num(txt('grossTotal','R$ 0,00'))),commission=Math.max(0,num(txt('summaryCommission','R$ 0,00'))),payout=Math.max(0,num(txt('netTotal','R$ 0,00'))),total=Math.max(gross,commission+payout),pct=total?commission/total*100:0;donut.style.background=`conic-gradient(#6d28d9 0 ${pct}%,#2583e8 ${pct}% 100%)`;donut.querySelector('span').innerHTML=`${t('total')}<br><b>${money(total)}</b><small>${t('commission')}: ${money(commission)}<br>Repasse: ${money(payout)}</small>`;donut.title=`${t('commission')}: ${money(commission)}; Repasse: ${money(payout)}`}}
