function updateHomeScope(){const m=document.getElementById('overviewMonthSelector'),y=document.getElementById('overviewYearSelector');if(!m||!y)return;const month=m.value,year=Number(y.value),months=month==='all'?Array.from({length:12},(_,i)=>({m:i,y,label:''})):[{m:Number(month)-1,y,label:''}],rows=chartSeries(months),tot=rows.reduce((a,r)=>({gross:a.gross+r.gross,expenses:a.expenses+r.expenses,cleaning:a.cleaning+r.cleaning,commission:a.commission+r.commission,before:a.before+r.before,net:a.net+r.net}),{gross:0,expenses:0,cleaning:0,commission:0,before:0,net:0}),props=chartProps(),reservations=[];props.forEach(p=>reservations.push(...chartRecords('ap207-dashboard-reservations-v1',p,'reservations')));const inMonth=d=>{const x=new Date(d);return x.getFullYear()===year&&(month==='all'||x.getMonth()+1===Number(month))},rs=reservations.filter(r=>r.status!=='Cancelada'&&inMonth(r.checkIn||r.date)),nights=rs.reduce((s,r)=>{const n=Number(r.nights);if(n)return s+n;const a=new Date(r.checkIn),b=new Date(r.checkOut);return s+(Number.isFinite(a.getTime())&&Number.isFinite(b.getTime())?Math.max(0,Math.round((b-a)/86400000)):0)},0),fmt=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val};set('periodCount',String(rs.length));set('nightCount',String(nights));set('nightRange',rs.length+' '+(rs.length===1?'período':'períodos'));set('grossTotal',fmt(tot.gross));set('summaryGross',fmt(tot.gross));set('summaryCleaning',fmt(tot.cleaning));set('summaryCommission',fmt(tot.commission));set('summaryNetBeforeExpenses',fmt(tot.before));set('summaryExpenses',fmt(tot.expenses));set('netTotal',fmt(tot.net));set('summaryNet',fmt(tot.net));const ml=document.getElementById('monthLabel');if(ml)ml.textContent=month==='all'?'Todos os meses de '+year:(m.options[m.selectedIndex]?.text+' de '+year);sync();updateCharts()}
